// The weekly goal. The ring fills toward it, and it resets with the week.
const GOAL = 300;
const EMBER = '#3a1f12';
const PEACH = '#ffe4d1';
const ORANGE = '#ff9447';
const BOLT = 'M13.5 2 4 14h6.5L9 22l11-13h-6.8z';
const DUMBBELL = 'M1.5 9.2a1.2 1.2 0 0 1 1.2-1.2h1.1a1.2 1.2 0 0 1 1.2 1.2v5.6a1.2 1.2 0 0 1-1.2 1.2H2.7a1.2 1.2 0 0 1-1.2-1.2z '
  + 'M5 7.2A1.2 1.2 0 0 1 6.2 6h1.1a1.2 1.2 0 0 1 1.2 1.2v9.6a1.2 1.2 0 0 1-1.2 1.2H6.2A1.2 1.2 0 0 1 5 16.8z '
  + 'M15.5 7.2A1.2 1.2 0 0 1 16.7 6h1.1A1.2 1.2 0 0 1 19 7.2v9.6a1.2 1.2 0 0 1-1.2 1.2h-1.1a1.2 1.2 0 0 1-1.2-1.2z '
  + 'M19 9.2A1.2 1.2 0 0 1 20.2 8h1.1a1.2 1.2 0 0 1 1.2 1.2v5.6a1.2 1.2 0 0 1-1.2 1.2h-1.1a1.2 1.2 0 0 1-1.2-1.2z '
  + 'M8.5 11.6a1 1 0 0 1 1-1h5a1 1 0 0 1 1 1v.8a1 1 0 0 1-1 1h-5a1 1 0 0 1-1-1z';

// A ring toward the goal, with a dumbbell in the middle.
function ring(fraction, u) {
  const size = 58 * u;
  const width = 6 * size / 54;
  return { type: 'zstack', frame: { width: size, height: size }, children: [
    { type: 'circle', padding: 3 * size / 54, stroke: { color: '#FFFFFF24', width } },
    fraction > 0 && { type: 'circle', padding: 3 * size / 54, trimTo: Math.min(1, fraction), rotation: -90,
      stroke: { color: ORANGE, width, cap: 'round' }, accent: true },
    { type: 'path', d: DUMBBELL, viewBox: [0, 0, 24, 24], fill: PEACH, frame: { width: 24 * u, height: 24 * u } },
  ] };
}

// The key's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one.
function key(u, ghost) {
  return { type: 'zstack', padding: { trailing: 15 * u, bottom: 15 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
    children: [
      { type: ghost ? 'zstack' : 'button', action: ghost ? null : 'ten', children: [
        { type: 'zstack', padding: { vertical: 8 * u, horizontal: 13 * u },
          background: { type: 'rect', cornerRadius: 10 * u, fill: ghost ? ORANGE : '#ff944740' }, children: [
            { type: 'text', value: '+10', size: 14 * u, weight: 'heavy', color: EMBER, opacity: ghost ? 0 : 1 },
          ] } ] },
    ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the count are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const line = (value) => ({ type: 'text', value, size: 12.5 * u, weight: 'semibold', color: PEACH, opacity: 0.8,
    lineLimit: 1 });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: EMBER,
      children: [key(u, true)] },
    children: [
      { type: 'zstack', padding: { top: 12 * u, trailing: 12 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [ring(d.week / GOAL, u)] },
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: BOLT, viewBox: [0, 0, 24, 24], fill: ORANGE, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: 'Pushups', size: 13 * u, weight: 'bold', color: ORANGE, lineLimit: 1 } ] },
          { type: 'text', value: d.week, fontName: 'Bricolage Grotesque Display', size: 44 * u, kerning: -1.32 * u,
            color: PEACH, accent: true, lineLimit: 1, minScale: 0.5, padding: { top: 3.6 * u },
            frame: { maxWidth: ctx.width - 100 * u, alignment: 'leading' } },
          { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 0.6 * u }, children: [
            line('this week'), line('goal ' + GOAL)] },
        ] },
      key(u, false),
    ],
  };
}
